--
-- test/repo_copy_check.sql -- prove each CAP_H_* copy equals its source on the target.
-- =====================================================================
-- GENERATED by repository/build.py from its source manifest. Do not edit:
-- change the manifest and run python3 repository/build.py
--
--   @test/repo_copy_check.sql [target|-] [plant_source|-]
--
-- Run as SYSDBA under ALTER SESSION SET CURRENT_SCHEMA = <repository schema>
-- (test/dbmint_copy_check.sh does), right after a collect. For every enabled
-- target (or the one named), each DBID it has collected and each source the
-- manifest copies, it compares the source over the target's link with the
-- copy both ways (source MINUS copy, copy MINUS source) and by row count:
--   F  snap_id from the later of the source's and the copy's oldest snap_id
--      (AWR purges the target, cap_repo.purge the copy) through the DBID's
--      high-water mark, the manifest's row filter on the source side; a copy
--      row above the high-water mark is a difference;
--   D  every row of the DBID, distinct on the source side as the MERGE is;
--   S  SEG_STAT_OBJ rows keyed by a SEG_STAT row of SEG_STAT's window.
-- A D or S copy keeps rows the target has since purged (cap_repo never
-- deletes dimension rows, e.g. DATABASE_INSTANCE of an aged-out startup), so
-- there only a source row missing from the copy is a difference; copy-only
-- rows are listed as kept. A stale copy of a keyed row still shows as its
-- source row missing.
-- Prints "COPYCHECK <target> dbid=<n> <source> ..." per source and DBID, its
-- first 10 differing rows, and one closing line
--   COPYCHECK-RESULT EQUAL | DIFFERENT | MOVED | FAILED ...
-- MOVED: the target took a snapshot or the high-water mark moved during the
-- check (purges and dimension rows ride on snapshots); rerun it.
-- plant_source names a fact (OSSTAT, ...): the check first deletes one copy
-- row of it, uncommitted, to prove a difference is caught, and this script
-- rolls it back (EXITCOMMIT OFF, ROLLBACK on error and at the end).
-- A private link resolves only for its owner, so the check runs in a
-- throwaway definer's-rights procedure, CAP_COPY_CHECK, dropped at the end.
--
SET APPINFO OFF
SET APPINFO "AWRCAP/test/repo_copy_check.sql"
SET DEFINE '&'
SET VERIFY OFF
SET FEEDBACK OFF
SET LINESIZE 32767
SET TAB OFF
SET TRIMOUT ON
SET TRIMSPOOL ON
SET EXITCOMMIT OFF
SET SERVEROUTPUT ON SIZE UNLIMITED FORMAT WRAPPED
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
COLUMN 1 NEW_VALUE 1
COLUMN 2 NEW_VALUE 2
SELECT NULL AS "1", NULL AS "2" FROM dual WHERE 1 = 0;

CREATE OR REPLACE PROCEDURE cap_copy_check(p_target IN VARCHAR2, p_plant IN VARCHAR2)
    AUTHID DEFINER AS
    TYPE t_num  IS TABLE OF NUMBER INDEX BY VARCHAR2(30);
    TYPE t_rows IS TABLE OF VARCHAR2(4000);
    v_lo      t_num;
    v_target  VARCHAR2(26);
    v_link    VARCHAR2(128);
    v_dbid    NUMBER;
    v_hwm     NUMBER;
    v_newest  NUMBER;
    v_checks  PLS_INTEGER := 0;
    v_diff    PLS_INTEGER := 0;
    v_fail    PLS_INTEGER := 0;
    v_rows    NUMBER := 0;
    v_moved   BOOLEAN := FALSE;
    v_t0      PLS_INTEGER := DBMS_UTILITY.GET_TIME;

    FUNCTION num(p_sql VARCHAR2) RETURN NUMBER IS
        v NUMBER;
    BEGIN
        EXECUTE IMMEDIATE p_sql INTO v;
        RETURN v;
    END num;

    PROCEDURE plant(p_name VARCHAR2) IS
        v_snap NUMBER := num('SELECT MAX(snap_id) FROM cap_h_' || p_name
                             || ' WHERE dbid = ' || v_dbid || ' AND snap_id <= ' || v_hwm);
    BEGIN
        EXECUTE IMMEDIATE 'DELETE FROM cap_h_' || p_name || ' WHERE dbid = ' || v_dbid
                          || ' AND snap_id = ' || v_snap || ' AND ROWNUM = 1';
        DBMS_OUTPUT.PUT_LINE('COPYCHECK-PLANTED CAP_H_' || UPPER(p_name) || ' dbid=' || v_dbid
                             || ' snap_id=' || v_snap || ' rows=' || SQL%ROWCOUNT);
    END plant;

    PROCEDURE one(p_name VARCHAR2, p_kind VARCHAR2, p_cols VARCHAR2, p_txt VARCHAR2,
                  p_filter VARCHAR2 DEFAULT NULL, p_scope VARCHAR2 DEFAULT NULL,
                  p_keys VARCHAR2 DEFAULT NULL) IS
        v_src    VARCHAR2(32767);
        v_copy   VARCHAR2(32767);
        v_win    VARCHAR2(100);
        v_n_src  NUMBER;
        v_n_copy NUMBER;
        v_side   VARCHAR2(10);
        v_row    VARCHAR2(4000);
        v_shown  t_rows := t_rows();
        v_o_src  PLS_INTEGER := 0;
        v_o_copy PLS_INTEGER := 0;
        v_cur    SYS_REFCURSOR;
        v_ok     BOOLEAN;
        v_where  VARCHAR2(4000) := CASE WHEN p_filter IS NOT NULL THEN ' AND (' || p_filter || ')' END;
    BEGIN
        v_src  := 'SELECT ' || CASE WHEN p_kind <> 'F' THEN 'DISTINCT ' END || p_cols
                  || ' FROM dba_hist_' || p_name || '@' || v_link || ' WHERE dbid = ' || v_dbid;
        v_copy := 'SELECT ' || p_cols || ' FROM cap_h_' || p_name || ' WHERE dbid = ' || v_dbid;
        IF p_kind = 'F' THEN
            v_lo(p_name) := GREATEST(
                NVL(num('SELECT MIN(snap_id) FROM dba_hist_' || p_name || '@' || v_link
                        || ' WHERE dbid = ' || v_dbid || v_where), 0),
                NVL(num('SELECT MIN(snap_id) FROM cap_h_' || p_name || ' WHERE dbid = ' || v_dbid), 0));
            v_src  := v_src || ' AND snap_id BETWEEN ' || v_lo(p_name) || ' AND ' || v_hwm || v_where;
            v_copy := v_copy || ' AND snap_id >= ' || v_lo(p_name);
            v_win  := ' snap ' || v_lo(p_name) || '..' || v_hwm;
            IF UPPER(p_plant) = UPPER(p_name) THEN
                plant(p_name);
            END IF;
        ELSIF p_kind = 'S' THEN
            v_src  := v_src || ' AND (' || p_keys || ') IN (SELECT ' || p_keys || ' FROM dba_hist_'
                      || p_scope || '@' || v_link || ' WHERE dbid = ' || v_dbid || ' AND snap_id BETWEEN '
                      || v_lo(p_scope) || ' AND ' || v_hwm || ')';
            v_copy := v_copy || ' AND (' || p_keys || ') IN (SELECT ' || p_keys || ' FROM cap_h_'
                      || p_scope || ' WHERE dbid = ' || v_dbid || ' AND snap_id BETWEEN '
                      || v_lo(p_scope) || ' AND ' || v_hwm || ')';
            v_win  := ' keys of ' || UPPER(p_scope) || ' ' || v_lo(p_scope) || '..' || v_hwm;
        END IF;
        v_n_src  := num('SELECT COUNT(*) FROM (' || v_src || ')');
        v_n_copy := num('SELECT COUNT(*) FROM (' || v_copy || ')');
        OPEN v_cur FOR 'SELECT ''SRC-ONLY'', ' || p_txt || ' FROM (' || v_src || ' MINUS ' || v_copy || ')'
                       || ' UNION ALL SELECT ''COPY-ONLY'', ' || p_txt || ' FROM (' || v_copy
                       || ' MINUS ' || v_src || ')';
        LOOP
            FETCH v_cur INTO v_side, v_row;
            EXIT WHEN v_cur%NOTFOUND;
            IF v_side = 'SRC-ONLY' THEN v_o_src := v_o_src + 1; ELSE v_o_copy := v_o_copy + 1; END IF;
            IF v_shown.COUNT < 10 THEN
                v_shown.EXTEND;
                v_shown(v_shown.COUNT) := '  ' || RPAD(CASE WHEN v_side = 'COPY-ONLY' AND p_kind <> 'F'
                                                            THEN 'KEPT' ELSE v_side END, 10)
                                          || UPPER(p_name) || ' ' || v_row;
            END IF;
        END LOOP;
        CLOSE v_cur;
        v_ok := v_o_src = 0 AND (p_kind <> 'F' OR v_n_src = v_n_copy AND v_o_copy = 0);
        v_checks := v_checks + 1;
        v_rows   := v_rows + v_n_src;
        IF NOT v_ok THEN
            v_diff := v_diff + 1;
        END IF;
        DBMS_OUTPUT.PUT_LINE('COPYCHECK ' || v_target || ' dbid=' || v_dbid || ' ' || RPAD(UPPER(p_name), 19)
                             || p_kind || v_win || ' src=' || v_n_src || ' copy=' || v_n_copy
                             || ' src_only=' || v_o_src || ' copy_only=' || v_o_copy
                             || CASE WHEN NOT v_ok THEN ' DIFF'
                                     WHEN v_o_copy > 0 THEN ' OK (copy-only rows kept)'
                                     ELSE ' OK' END);
        FOR i IN 1 .. v_shown.COUNT LOOP
            DBMS_OUTPUT.PUT_LINE(v_shown(i));
        END LOOP;
    EXCEPTION
        WHEN OTHERS THEN
            v_fail := v_fail + 1;
            DBMS_OUTPUT.PUT_LINE('COPYCHECK ' || v_target || ' dbid=' || v_dbid || ' '
                                 || RPAD(UPPER(p_name), 19) || 'ERROR ' || SQLERRM);
    END one;

    FUNCTION newest RETURN NUMBER IS
    BEGIN
        RETURN num('SELECT MAX(snap_id) FROM dba_hist_snapshot@' || v_link || ' WHERE dbid = ' || v_dbid);
    END newest;
BEGIN
    FOR t IN (SELECT t.target_name, t.db_link, d.dbid, d.last_snap_id
              FROM   cap_target t JOIN cap_target_dbid d ON d.target_id = t.target_id
              WHERE  (t.target_name = UPPER(p_target) OR p_target IS NULL AND t.enabled = 'Y')
                AND  d.last_snap_id > 0
              ORDER  BY t.target_name, d.dbid) LOOP
        v_target := t.target_name;
        v_link   := t.db_link;
        v_dbid   := t.dbid;
        v_hwm    := t.last_snap_id;
        v_lo.DELETE;
        BEGIN
            v_newest := newest;
            one('snapshot',
                'F',
                q'~dbid, instance_number, snap_id, startup_time, begin_interval_time, end_interval_time~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(startup_time, 'YYYY-MM-DD HH24:MI:SS.FF3') || '|' || TO_CHAR(begin_interval_time, 'YYYY-MM-DD HH24:MI:SS.FF3') || '|' || TO_CHAR(end_interval_time, 'YYYY-MM-DD HH24:MI:SS.FF3')~');
            one('tbspc_space_usage',
                'F',
                q'~dbid, con_dbid, snap_id, tablespace_id, tablespace_size, tablespace_maxsize, tablespace_usedsize~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(tablespace_id) || '|' || TO_CHAR(tablespace_size) || '|' || TO_CHAR(tablespace_maxsize) || '|' || TO_CHAR(tablespace_usedsize)~');
            one('osstat',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, stat_name, value~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || stat_name || '|' || TO_CHAR(value)~',
                p_filter => q'~stat_name IN ('BUSY_TIME','IDLE_TIME','IOWAIT_TIME','NUM_CPUS','NUM_CPU_CORES','PHYSICAL_MEMORY_BYTES')~');
            one('sys_time_model',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, stat_name, value~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || stat_name || '|' || TO_CHAR(value)~',
                p_filter => q'~stat_name IN ('DB CPU','DB time','background cpu time')~');
            one('con_sys_time_model',
                'F',
                q'~dbid, con_dbid, con_id, instance_number, snap_id, stat_name, value~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(con_id) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || stat_name || '|' || TO_CHAR(value)~',
                p_filter => q'~stat_name IN ('DB CPU','DB time','background cpu time')~');
            one('resource_limit',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, resource_name, current_utilization, max_utilization, limit_value~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || resource_name || '|' || TO_CHAR(current_utilization) || '|' || TO_CHAR(max_utilization) || '|' || limit_value~',
                p_filter => q'~resource_name IN ('processes','sessions')~');
            one('sysstat',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, stat_name, value~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || stat_name || '|' || TO_CHAR(value)~',
                p_filter => q'~stat_name IN ('redo size',
             'physical read total IO requests','physical write total IO requests',
             'physical read total bytes','physical write total bytes')~');
            one('con_sysstat',
                'F',
                q'~dbid, con_dbid, con_id, instance_number, snap_id, stat_name, value~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(con_id) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || stat_name || '|' || TO_CHAR(value)~',
                p_filter => q'~stat_name IN ('redo size',
             'physical read total IO requests','physical write total IO requests',
             'physical read total bytes','physical write total bytes')~');
            one('parameter',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, parameter_name, value~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || parameter_name || '|' || value~',
                p_filter => q'~parameter_name IN ('cpu_count','processes','sessions','db_recovery_file_dest_size','sga_target','sga_max_size','pga_aggregate_target','pga_aggregate_limit','memory_target')~');
            one('asm_diskgroup_stat',
                'F',
                q'~dbid, con_dbid, snap_id, group_number, total_mb, free_mb~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(group_number) || '|' || TO_CHAR(total_mb) || '|' || TO_CHAR(free_mb)~');
            one('seg_stat',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, ts#, obj#, dataobj#, space_used_delta, space_allocated_delta~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(ts#) || '|' || TO_CHAR(obj#) || '|' || TO_CHAR(dataobj#) || '|' || TO_CHAR(space_used_delta) || '|' || TO_CHAR(space_allocated_delta)~');
            one('pgastat',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, name, value~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || name || '|' || TO_CHAR(value)~');
            one('mem_dynamic_comp',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, component, current_size, min_size, max_size, user_specified_size, oper_count, last_oper_type, last_oper_mode, last_oper_time, granule_size~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || component || '|' || TO_CHAR(current_size) || '|' || TO_CHAR(min_size) || '|' || TO_CHAR(max_size) || '|' || TO_CHAR(user_specified_size) || '|' || TO_CHAR(oper_count) || '|' || last_oper_type || '|' || last_oper_mode || '|' || last_oper_time || '|' || TO_CHAR(granule_size)~');
            one('sql_workarea_hstgrm',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, low_optimal_size, high_optimal_size, optimal_executions, onepass_executions, multipasses_executions, total_executions~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(low_optimal_size) || '|' || TO_CHAR(high_optimal_size) || '|' || TO_CHAR(optimal_executions) || '|' || TO_CHAR(onepass_executions) || '|' || TO_CHAR(multipasses_executions) || '|' || TO_CHAR(total_executions)~');
            one('pga_target_advice',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, pga_target_for_estimate, pga_target_factor, advice_status, bytes_processed, estd_time, estd_extra_bytes_rw, estd_pga_cache_hit_percentage, estd_overalloc_count~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(pga_target_for_estimate) || '|' || TO_CHAR(pga_target_factor) || '|' || advice_status || '|' || TO_CHAR(bytes_processed) || '|' || TO_CHAR(estd_time) || '|' || TO_CHAR(estd_extra_bytes_rw) || '|' || TO_CHAR(estd_pga_cache_hit_percentage) || '|' || TO_CHAR(estd_overalloc_count)~');
            one('sga_target_advice',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, sga_size, sga_size_factor, estd_db_time, estd_physical_reads~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(sga_size) || '|' || TO_CHAR(sga_size_factor) || '|' || TO_CHAR(estd_db_time) || '|' || TO_CHAR(estd_physical_reads)~');
            one('db_cache_advice',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, bpid, name, block_size, advice_status, size_for_estimate, size_factor, buffers_for_estimate, physical_reads, base_physical_reads, actual_physical_reads, estd_physical_read_time~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(bpid) || '|' || name || '|' || TO_CHAR(block_size) || '|' || advice_status || '|' || TO_CHAR(size_for_estimate) || '|' || TO_CHAR(size_factor) || '|' || TO_CHAR(buffers_for_estimate) || '|' || TO_CHAR(physical_reads) || '|' || TO_CHAR(base_physical_reads) || '|' || TO_CHAR(actual_physical_reads) || '|' || TO_CHAR(estd_physical_read_time)~');
            one('shared_pool_advice',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, shared_pool_size_for_estimate, shared_pool_size_factor, estd_lc_size, estd_lc_memory_objects, estd_lc_time_saved, estd_lc_time_saved_factor, estd_lc_load_time, estd_lc_load_time_factor, estd_lc_memory_object_hits~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || TO_CHAR(shared_pool_size_for_estimate) || '|' || TO_CHAR(shared_pool_size_factor) || '|' || TO_CHAR(estd_lc_size) || '|' || TO_CHAR(estd_lc_memory_objects) || '|' || TO_CHAR(estd_lc_time_saved) || '|' || TO_CHAR(estd_lc_time_saved_factor) || '|' || TO_CHAR(estd_lc_load_time) || '|' || TO_CHAR(estd_lc_load_time_factor) || '|' || TO_CHAR(estd_lc_memory_object_hits)~');
            one('sgastat',
                'F',
                q'~dbid, con_dbid, con_id, instance_number, snap_id, pool, name, bytes~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(con_id) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || pool || '|' || name || '|' || TO_CHAR(bytes)~',
                p_filter => q'~name = 'free memory'~');
            one('librarycache',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, namespace, gets, gethits, pins, pinhits, reloads, invalidations~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || namespace || '|' || TO_CHAR(gets) || '|' || TO_CHAR(gethits) || '|' || TO_CHAR(pins) || '|' || TO_CHAR(pinhits) || '|' || TO_CHAR(reloads) || '|' || TO_CHAR(invalidations)~');
            one('rowcache_summary',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, parameter, gets, getmisses~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || parameter || '|' || TO_CHAR(gets) || '|' || TO_CHAR(getmisses)~');
            one('system_event',
                'F',
                q'~dbid, con_dbid, instance_number, snap_id, event_name, wait_class, total_waits, time_waited_micro~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(snap_id) || '|' || event_name || '|' || wait_class || '|' || TO_CHAR(total_waits) || '|' || TO_CHAR(time_waited_micro)~',
                p_filter => q'~event_name IN (
             'free buffer waits',
             'write complete waits',
             'buffer busy waits',
             'latch: cache buffers lru chain',
             'latch: shared pool',
             'library cache: mutex X',
             'library cache load lock',
             'library cache lock',
             'cursor: pin S wait on X',
             'SGA: allocation forcing component growth',
             'latch: row cache objects',
             'row cache lock',
             'row cache mutex',
             'direct path read temp',
             'direct path write temp')~');
            one('tablespace',
                'D',
                q'~dbid, con_dbid, ts#, tsname, contents, block_size~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(ts#) || '|' || tsname || '|' || contents || '|' || TO_CHAR(block_size)~');
            one('datafile',
                'D',
                q'~dbid, con_dbid, ts#, block_size~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(ts#) || '|' || TO_CHAR(block_size)~');
            one('pdb_instance',
                'D',
                q'~dbid, con_dbid, pdb_name~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || pdb_name~');
            one('database_instance',
                'D',
                q'~dbid, instance_number, startup_time, db_name, host_name~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(instance_number) || '|' || TO_CHAR(startup_time, 'YYYY-MM-DD HH24:MI:SS.FF3') || '|' || db_name || '|' || host_name~');
            one('asm_diskgroup',
                'D',
                q'~dbid, con_dbid, group_number, name~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(group_number) || '|' || name~');
            one('seg_stat_obj',
                'S',
                q'~dbid, con_dbid, ts#, obj#, dataobj#, owner, object_name, subobject_name, object_type, tablespace_name~',
                q'~TO_CHAR(dbid) || '|' || TO_CHAR(con_dbid) || '|' || TO_CHAR(ts#) || '|' || TO_CHAR(obj#) || '|' || TO_CHAR(dataobj#) || '|' || owner || '|' || object_name || '|' || subobject_name || '|' || object_type || '|' || tablespace_name~',
                p_scope => 'seg_stat',
                p_keys => q'~dbid, con_dbid, ts#, obj#, dataobj#~');
            IF newest <> v_newest
               OR num('SELECT last_snap_id FROM cap_target_dbid WHERE dbid = ' || v_dbid) <> v_hwm THEN
                v_moved := TRUE;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                v_fail := v_fail + 1;
                DBMS_OUTPUT.PUT_LINE('COPYCHECK ' || v_target || ' dbid=' || v_dbid || ' ERROR ' || SQLERRM);
        END;
    END LOOP;
    DBMS_OUTPUT.PUT_LINE('COPYCHECK-RESULT '
        || CASE WHEN v_fail > 0 THEN 'FAILED'
                WHEN v_checks = 0 THEN 'FAILED (no collected DBID of an enabled target)'
                WHEN v_moved THEN 'MOVED'
                WHEN v_diff > 0 THEN 'DIFFERENT'
                ELSE 'EQUAL' END
        || ' checks=' || v_checks || ' differing=' || v_diff || ' errors=' || v_fail
        || ' rows=' || v_rows || ' seconds=' || ROUND((DBMS_UTILITY.GET_TIME - v_t0) / 100, 1));
END cap_copy_check;
/
SHOW ERRORS

WHENEVER SQLERROR CONTINUE
EXEC cap_copy_check(NULLIF('&1', '-'), NULLIF('&2', '-'))
ROLLBACK;
DROP PROCEDURE cap_copy_check;
UNDEFINE 1 2
